// Inline the reviewed calendar source and unmodified MPL-2.0 dependency for
// Obsidian's single-file plugin loader, including mobile. No package install.
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
const start='// BEGIN LOCAL CALENDAR BUNDLE';
const target=path.join(root,'main.js');
const main=fs.readFileSync(target,'utf8').split(start)[0].trimEnd();
const links=fs.readFileSync(path.join(root,'meeting-links.js'),'utf8').replace('module.exports =', 'return');
const linksBundle=`\nfunction getHomeMeetingLinks() {\n${links}\n}\n`;
const vendor=fs.readFileSync(path.join(root,'vendor/ical.cjs'),'utf8');
const adapter=fs.readFileSync(path.join(root,'calendar.js'),'utf8')
 .replace("const ICAL = require('./vendor/ical.cjs');",'')
 .replace("require('./meeting-links.js')",'getHomeMeetingLinks()')
 .replace('module.exports = { validateGoogleCalendarUrl, calendarAgenda };','return { validateGoogleCalendarUrl, calendarAgenda };');
const bundle=`\n\n${start}\n// Generated by scripts/bundle-calendar.cjs; edit calendar.js, not this section.\nlet homeCalendarAdapter;\nfunction getHomeCalendarAdapter() {\n  if (!homeCalendarAdapter) homeCalendarAdapter = (() => {\n    const ICAL = (() => { const module = { exports: {} }; const exports = module.exports;\n${vendor}\nreturn module.exports; })();\n${adapter}\n  })();\n  return homeCalendarAdapter;\n}\n// END LOCAL CALENDAR BUNDLE\n`;
const google=fs.readFileSync(path.join(root,'google-calendar.js'),'utf8').replace('module.exports=', 'return ').replace("require('./meeting-links.js')",'getHomeMeetingLinks()');
const googleBundle=`\nlet homeGoogleAdapter;\nfunction getHomeGoogleAdapter() {\n  if (!homeGoogleAdapter) homeGoogleAdapter = (() => {\n${google}\n  })();\n  return homeGoogleAdapter;\n}\n`;
fs.writeFileSync(target,main+bundle+googleBundle+linksBundle);
console.log('Bundled ICAL.js 2.2.1 and local read-only calendar adapter into main.js');
